const App: React.FC = () => {
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [isAuthOpen, setIsAuthOpen] = useState(false);
  const [authMode, setAuthMode] = useState<'signin' | 'signup'>('signup');
  const [currentUser, setCurrentUser] = useState<UserProfile | null>(null);
  const [showWelcomeModal, setShowWelcomeModal] = useState(false);

  // Navigation State
  const [view, setView] = useState<'landing' | 'dashboard'>('landing');

  // Global Language State
  const [language, setLanguage] = useState<'English' | 'Hindi' | 'Bengali'>('English');
  const [isLangMenuOpen, setIsLangMenuOpen] = useState(false);

  // Access current translations
  const t = translations[language];

  useEffect(() => {
    if (localStorage.getItem('theme') === 'dark' || (!('theme' in localStorage) && window.matchMedia('(prefers-color-scheme: dark)').matches)) {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDarkMode) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDarkMode(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDarkMode(true);
    }
  };

  const scrollToBooking = () => {
    const bookingElement = document.getElementById('booking');
    if (bookingElement) {
        bookingElement.scrollIntoView({ behavior: 'smooth' });
    }
  };

  const startNicheAnalysis = (prompt: string) => {
      scrollToBooking();
  };

  const openAuth = (mode: 'signin' | 'signup') => {
    setAuthMode(mode);
    setIsAuthOpen(true);
  };

  const handleAuthSuccess = (user: UserProfile) => {
    setCurrentUser(user);
    if (user.language && (user.language === 'English' || user.language === 'Hindi' || user.language === 'Bengali')) {
        setLanguage(user.language as any);
    }
    if (user.isNewUser) {
      setShowWelcomeModal(true);
    } else {
      setView('dashboard'); // Auto-redirect returning users
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setView('landing');
  };

  const handleLanguageChange = (lang: 'English' | 'Hindi' | 'Bengali') => {
      setLanguage(lang);
      setIsLangMenuOpen(false);
  };

  // If viewing Dashboard, render full screen Dashboard Component
  if (view === 'dashboard' && currentUser) {
      return <Dashboard user={currentUser} onLogout={handleLogout} />;
  }

  return (
    <div className="min-h-screen flex flex-col font-sans text-slate-600 dark:text-slate-300 transition-colors duration-300">

      {/* Authentication Modal */}
      <AuthModal 
        isOpen={isAuthOpen} 
        onClose={() => setIsAuthOpen(false)} 
        initialMode={authMode} 
        onAuthSuccess={handleAuthSuccess}
      />

      {/* Welcome Modal for New Users */}
      <WelcomeModal 
        isOpen={showWelcomeModal}
        onClose={() => setShowWelcomeModal(false)}
        onStart={() => {
            setShowWelcomeModal(false);
            setView('dashboard');
        }}
        userName={currentUser?.name || "User"}
      />

      {/* Navbar */}
      <nav className="sticky top-0 z-50 bg-white/90 dark:bg-slate-900/90 backdrop-blur-md border-b border-slate-100 dark:border-slate-800 transition-colors duration-300">
