          <div className="flex justify-between items-center h-20">
            <div className="flex items-center gap-2 sm:gap-3 group cursor-pointer" onClick={() => setView('landing')}>
              <BrandLogo className="w-10 h-10 md:w-12 md:h-12 transition-transform group-hover:scale-105" />
              <div className="flex flex-col">
                  <span className="font-bold text-lg md:text-xl tracking-tight text-navy-900 dark:text-white leading-none">SimpleAgentix</span>
                  <span className="text-[9px] md:text-[10px] uppercase font-bold text-vibrant-orange tracking-widest leading-none mt-1">Automation</span>
              </div>
            </div>
            <div className="hidden md:flex items-center gap-8">
              <a href="#features" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.features}</a>
              <a href="#pricing" className="text-sm font-medium hover:text-navy-900 dark:hover:text-white transition-colors">{t.nav.pricing}</a>
